const severityOrder: Record<string, number> = { 高: 0, 中: 1, 低: 2 }

// 影响列写色觉类型全称,用顿号连接;空数组留空。
const issueRows = [...data.issues]
  .sort(
    (a, b) =>
      (severityOrder[a.severity] ?? 9) - (severityOrder[b.severity] ?? 9) ||
      a.id.localeCompare(b.id),
  )
  .map((i) => ({
    id: i.id,
    severity: i.severity,
    title: i.title,
    suggestion: i.suggestion,
    type: i.type,
    location: i.location,
    affects: i.affects.join("、"),
  }))

// 同长取编号小的:候选按编号排序后再比。
const issueByIdSorted = [...issueRows].sort((a, b) => a.id.localeCompare(b.id))

// 两段文字里最长的一段连续相同文字。
const commonText = (a: string, b: string) => {
  let best = 0
  for (let i = 0; i < a.length; i++) {
    for (let j = 0; j < b.length; j++) {
      let k = 0
      while (a[i + k] && a[i + k] === b[j + k]) k++
      if (k > best) best = k
    }
  }
  return best
}

// 明细表编号:与该行 where 指同一处、或有 3 个以上连续相同文字的那条问题。
const detailIssueId = (where: string) => {
  const samePlace = issueByIdSorted.find((r) => r.location === where)
  if (samePlace) return samePlace.id
  let bestId = ""
  let bestLen = 2
  for (const r of issueByIdSorted) {
    for (const field of [r.title, r.suggestion]) {
      const len = commonText(where, field)
      if (len > bestLen) {
        bestLen = len
        bestId = r.id
      }
    }
  }
  return bestId
}

// 明细表:标了编号的行「位置」写该条问题的位置,否则写检查项原文。
const detailRows = <T extends { where: string }>(rows: T[]) =>
  rows.map((r) => {
    const id = detailIssueId(r.where)
    const issue = issueByIdSorted.find((i) => i.id === id)
    return { ...r, id, where: issue ? issue.location : r.where }
  })

// Which simulated types lose the colour pair: the affected ΔE sits in that type's column.
const affectedTone = (type: "红色盲" | "绿色盲" | "蓝色盲") =>
  data.confusions.filter((c) => c.affected.includes(type)).map((c) => String(c[type]))

const contrastRows = detailRows(data.contrast).map((c) => ({
  id: c.id,
  where: c.where,
  fg: c.fg,
  bg: c.bg,
  ratio: c.ratio,
  required: c.required,
  state: c.pass ? "达标" : "不达标",
}))

const confusionRows = detailRows(data.confusions).map((c) => ({
  id: c.id,
  where: c.where,
  normal: c.normal,
  红色盲: c["红色盲"],
  绿色盲: c["绿色盲"],
  蓝色盲: c["蓝色盲"],
  affected: c.affected.length ? c.affected.join("、") : "—",
}))

// 修复动作的问题编号:先按文字匹配问题,再取同 where 明细行的编号,都取不到留空。
const detailIdByWhere = new Map<string, string>()
for (const r of [...data.contrast, ...data.confusions]) {
  detailIdByWhere.set(r.where, detailIssueId(r.where))
}

const matchFixIssueId = (where: string) => {
  for (const field of ["location", "title", "suggestion"] as const) {
    let bestId = ""
    let bestLen = 1
    for (const r of issueByIdSorted) {
      const len = commonText(where, r[field])
      if (len > bestLen) {
        bestLen = len
        bestId = r.id
      }
    }
    if (bestId) return bestId
  }
  return detailIdByWhere.get(where) ?? ""
}

const fixRows = data.fixes.map((f) => ({
  id: matchFixIssueId(f.where),
  where: f.where,
  from: f.from,
  to: f.to,
  before: f.before,
  after: f.after,
  bg: f.bg,
}))

// 每条问题在修复动作表里匹配到的改前改后数值。
const fixMeta = new Map<string, string[]>()
for (const f of data.fixes) {
  const id = matchFixIssueId(f.where)
  if (!id) continue
  const list = fixMeta.get(id) ?? []
  list.push(`${f.from} → ${f.to},${f.before} → ${f.after}`)
  fixMeta.set(id, list)
}

